        self.queue1 = []
        self.queue2 = []

    def push(self, data):
        # Push the data to queue 1
        self.queue1.append(data)

    def pop(self):
        # Move all elements from queue 1 to queue 2 except the last one
        while len(self.queue1) > 1:
            self.queue2.append(self.queue1.pop(0))

        # Pop the last element from queue 1
        popped_element = self.queue1.pop(0)

        # Swap the names of the two queues
        self.queue1, self.queue2 = self.queue2, self.queue1

