def flatten_list(nested_list):
    # Base case: if the list is empty, return an empty list
    if not nested_list:
        return []

    # Recursive case: if the first element of the list is a list,
    # recursively flatten it and concatenate it with the rest of the list
    if isinstance(nested_list[0], list):
        return flatten_list(nested_list[0]) + flatten_list(nested_list[1:])

    # Otherwise, add the first element to the result and recursively flatten the rest of the list
    else:
        return [nested_list[0]] + flatten_list(nested_list[1:])

