def luhn_algorithm(number):
    # Reverse the number
    number = str(number)[::-1]

    # Double every second digit
    for i in range(0, len(number), 2):
        number[i] = str(int(number[i]) * 2)

    # Subtract 9 from any number over 9
    for i in range(0, len(number)):
        if int(number[i]) > 9:
            number[i] = str(int(number[i]) - 9)

    # Sum all the digits
    total = 0
    for i in range(0, len(number)):
        total += int(number[i])

    # Check if the sum is divisible by 10
    if total % 10 == 0:
        return True
    else:
        return False

def factorial(n):
    # Base case: if n is 0 or 1, return 1
    if n == 0 or n == 1:
        return 1

    # Recursive case: multiply n with the factorial of (n-1)
    else:
        return n * factorial(n-1)

