def permute(nums):
    if len(nums) == 0:
        return []

    if len(nums) == 1:
        return [nums]

    perm_list = []
    for i in range(len(nums)):
        m = nums[i]
        remaining_list = nums[:i] + nums[i+1:]

        for p in permute(remaining_list):
            perm_list.append([m] + p)

