import functools

def logging(func):

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print(f'Calling {func.__name__}')
        return func(*args, **kwargs)
    return wrapper

def retry(Exception, tries=3, delay=3):
    """Retries a function or method until it returns successfully.

    Args:
        Exception: The exception to catch.
        tries: Number of times to try (default 3).
        delay: Time to wait between retries in seconds (default 3).

    Returns:
        The result of the function or method call.
    """

    @logging
    def decorator(func):

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for i in range(tries):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if i == tries - 1:
                        raise
                    print('Exception thrown when retrying, sleeping {} seconds'.format(delay))
                    time.sleep(delay)
            return None
        return wrapper
    return decorator

