def separate_list(nums):
    prime_nums = []
    composite_nums = []
    odd_even_nums = []

    for num in nums:
        if num > 1:
            for i in range(2,num):
                if (num % i) == 0:
                    composite_nums.append(num)
                    break
            else:
                prime_nums.append(num)

        elif num % 2 == 0:
            composite_nums.append(num)
        else:
            odd_even_nums.append(num)
    return prime_nums, composite_nums, odd_even_nums

