def compress_string(s): 
    # Count occurences of each character 
    dict = {} 
    for c in s: 
        if c in dict: 
            dict[c] += 1
        else: 
            dict[c] = 1

    # Create a new string with the format 
    # <character><number_of_occurences>
    compressed_str = [] 
    for key,value in dict.items(): 
        compressed_str.append(key + str(value)) 

    return ''.join(compressed_str)

def levenshtein_distance(str1, str2):
    m = len(str1)
    n = len(str2)

    edit_distance = [[0 for i in range(n+1)] for j in range(m+1)]

    for i in range(m+1):
        for j in range(n+1):
            if i == 0:
                edit_distance[i][j] = j
            elif j == 0:
                edit_distance[i][j] = i
            elif str1[i-1] == str2[j-1]:
                edit_distance[i][j] = edit_distance[i-1][j-1]
            else:
                edit_distance[i][j] = 1 + min(edit_distance[i][j-1],
                                            edit_distance[i-1][j],
                                            edit_distance[i-1][j-1])

    return edit_distance[m][n]

