class Stack:
    def __init__(self):
        self.queue1 = []
        self.queue2 = []

    def push(self, data):
        # Push the element to queue 1
        self.queue1.append(data)

    def pop(self):
        # Move all elements from queue 1 to queue 2 except the last one
        while len(self.queue1) > 1:
            temp = self.queue1.pop(0)
            self.queue2.append(temp)

        # The last element is the top of the stack, so pop it and swap the names of the two queues
        top = self.queue1.pop(0)
        self.queue1, self.queue2 = self.queue2, self.queue1
        return top

