        new_node = Node(val)
        if not self.root:
            self.root = new_node
        else:
            curr_node = self.root
            while True:
                if val < curr_node.val:
                    if curr_node.left:
                        curr_node = curr_node.left
                    else:
                        curr_node.left = new_node
                        break
                elif val > curr_node.val:
