def retry(Exception, tries=3, delay=1):
    """Rteurs a decorator that retries a function a number of times."""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for i in range(tries):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if i == tries - 1:
                        raise
                    time.sleep(delay)
            return None
        return wrapper
    return decorator

