def merge_dicts(dict1, dict2):
    merged_dict = {}

    # Iterate through the first dictionary
    for key in dict1:
        if key in dict2:
            # If key is present in both, add the values
            merged_dict[key] = dict1[key] + dict2[key]
        else:
            # Otherwise, set the value from the first dictionary
            merged_dict[key] = dict1[key]

    # Iterate through the second dictionary
    for key in dict2:
        if key not in dict1:
            # Add new keys from the second dictionary
            merged_dict[key] = dict2[key]

    return merged_dict

