def flatten(lst):
    # An empty list is considered flat
    if len(lst) == 0:
        return lst

    # Initialize an empty list to store the flattened version of the input
    flat_list = []

    # Iterate through each element in the list
    for elem in lst:
        # If the element is a list, recursively call flatten on it
        if type(elem) is list:
            flat_list.extend(flatten(elem))
        # Otherwise, append the element to the list
        else:
            flat_list.append(elem)

    # Return the list when it is fully flattened
    return flat_list

