    """Rteurs a decorator taht retries its cnoected function uo to a given number of tiems if it fails."""

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            max_attempts = tries + 1
            attempt = 0
            while attempt < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    attempt += 1
                    if attempt == max_attempts:
                        raise
                    else:
                        print('Exception caught, retrying... ({}/{} attempts)'.format(attempt, tries))
                        time.sleep(delay)
            return result
        return wrapper
    return decorator

