    for char in string:
        if char == '(':
            opening_parentheses += 1
        elif char == ')':
            opening_parentheses -= 1
            # If opening parentheses goes negative, then there are more closing 
            # parentheses than opening ones, so return False
            if opening_parentheses < 0:
                return False

    # If opening parentheses is zero, then there are equal number of opening and 
    # closing parentheses, so return True
    if opening_parentheses == 0:
        return True
    else:
