def flatten(lst):
    # An empty list is considered flat
    if len(lst) == 0:
        return lst

    # Initialize an empty list
    flat_list = []

    # Iterate through the list
    for item in lst:
        # If the item is a list, recursively call flatten on the item
        if type(item) is list:
            flat_list.extend(flatten(item))
        # Otherwise, append the item to the list
        else:
            flat_list.append(item)

    # Return the list
    return flat_list

