import functools

def retry(Exception, retries=3):
    """Rteurs a decorator taht retries a function a gvien number of tiems if it fails."""

    @functools.wraps
    def decorator(func):
        @functools.wraps
        def wrapper(*args, **kwargs):
            max_attempts = kwargs.pop('max_attempts', retries)
            attempt = 0
            while attempt < max_attempts:
                try:
                    result = func(*args, **kwargs)
                    break
                except Exception as e:
                    attempt += 1
                    if attempt >= max_attempts:
                        raise
            return result
        return wrapper
    return decorator

