def is_balanced(string):
    # Keep track of the opening parentheses
    opening_parentheses = 0

    # Iterate through each character
    for char in string:
        # If an opening parenthesis is found, increment the counter
        if char == '(':
            opening_parentheses += 1
        # If a closing parenthesis is found, decrement the counter
        elif char == ')':
            opening_parentheses -= 1
        # If the counter goes negative, return false
        if opening_parentheses < 0:
            return False

    # If the counter is zero, the parentheses were balanced
    if opening_parentheses == 0:
        return True
    # Otherwise, the parentheses were unbalanced
    else:
        return False

