def is_anagram(string1, string2):
    # Remove whitespace and covert strings to lowercase
    string1 = string1.replace(" ", "").lower()
    string2 = string2.replace(" ", "").lower()

    # Check lengths. If lengths differ, strings cannot be anagrams
    if len(string1) != len(string2):
        return False

    # Create dictionaries containing characters of each string
    char_count1 = {}
    char_count2 = {}

    # Fill dictionaries with characters as key and count as value
    for char in string1:
        if char in char_count1:
            char_count1[char] += 1
        else:
            char_count1[char] = 1

    for char in string2:
        if char in char_count2:
            char_count2[char] += 1
        else:
            char_count2[char] = 1

    # If dictionaries are equal, then both string are anagrams
    return char_count1 == char_count2

